322	    /** Insert a row with the given id, or a generated one when none is given; returns the id. */
323	    private Long insert(String table, Object id, String[] columns, Object... values) {
324	        String cols = String.join(", ", columns);
325	        String marks = String.join(", ", Collections.nCopies(columns.length, "?"));
326	        if (id != null) {
327	            Object[] args = new Object[values.length + 1];
328	            args[0] = id(id);
329	            System.arraycopy(values, 0, args, 1, values.length);
330	            jdbc.update("INSERT INTO " + table + " (id, " + cols + ") VALUES (?, " + marks + ")", args);
331	            return id(id);
332	        }
333	        jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")", values);
334	        return jdbc.queryForObject("SELECT MAX(id) FROM " + table, Long.class);
335	    }
