376	    private static BigDecimal cents(Object value, String field) {
377	        if (value == null) {
378	            throw refuse(field + " is required");
379	        }
380	        BigDecimal number;
381	        try {
382	            number = new BigDecimal(value.toString());
383	        } catch (NumberFormatException e) {
384	            throw refuse(field + " must be a number, not " + value);
385	        }
386	        if (number.stripTrailingZeros().scale() > 2) {
387	            throw refuse(field + " can have at most two decimals, not " + value);
388	        }
389	        return number;
