397	        BigDecimal number = cents(value, field);
398	        if (number.signum() < 0 || number.compareTo(BigDecimal.valueOf(100)) > 0) {
399	            throw refuse(field + " must be from 0 to 100, not " + value);
400	        }
401	        return number;
402	    }
