810	    public List<BigDecimal> discountShares() {
811	        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
812	        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
813	        int n = lines.size();
814	        BigInteger[] shares = new BigInteger[n];
815	        BigInteger[] leftovers = new BigInteger[n];
816	        BigInteger given = BigInteger.ZERO;
817	        for (int i = 0; i < n; i++) {
818	            if (subtotalCents.signum() == 0) {
819	                shares[i] = BigInteger.ZERO;
820	                leftovers[i] = BigInteger.ZERO;
