831	        List<Integer> order = new ArrayList<>();
832	        for (int i = 0; i < n; i++) {
833	            order.add(i);
834	        }
835	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
