945	/**
946	 * An invoice's number, made from its id: INV-, the id padded to six digits, then a Luhn check
947	 * digit over those six digits — so invoice 7 is INV-0000075.
948	 */
949	public final class InvoiceNumber {
950	
951	    private static final Pattern FORM = Pattern.compile("INV-(\\d{6})(\\d)");
952	
953	    private InvoiceNumber() {
954	    }
955	
956	    /** The number of the invoice with this id. */
957	    public static String of(long id) {
958	        String digits = String.format("%06d", id);
959	        return "INV-" + digits + checkDigit(digits);
960	    }
961	
962	    /**
963	     * The invoice id a typed number stands for. Empty when it is not of the form INV-nnnnnnn or its
964	     * check digit does not match — the number was mistyped.
965	     */
966	    public static Optional<Long> idOf(String typed) {
967	        Matcher m = FORM.matcher(typed.trim().toUpperCase());
968	        if (!m.matches() || checkDigit(m.group(1)) != m.group(2).charAt(0) - '0') {
969	            return Optional.empty();
970	        }
971	        return Optional.of(Long.parseLong(m.group(1)));
972	    }
973	
974	    /**
975	     * Luhn: from the rightmost digit, double every second digit (the rightmost, the third from the
976	     * right, ...), subtracting 9 from any result over 9; the check digit brings the sum of all the
977	     * digits up to the next multiple of ten.
978	     */
979	    static int checkDigit(String digits) {
980	        int sum = 0;
981	        for (int i = 0; i < digits.length(); i++) {
982	            int d = digits.charAt(digits.length() - 1 - i) - '0';
983	            if (i % 2 == 0) {
984	                d *= 2;
985	                if (d > 9) {
986	                    d -= 9;
987	                }
988	            }
989	            sum += d;
990	        }
991	        return (10 - sum % 10) % 10;
992	    }
993	}
